<template>
  <section class="page">
    <header class="hero"><div><p class="eyebrow">STORY AGENT · STAGE 8 · PROFESSIONAL RELEASE OPERATIONS</p><h2>Stage 8 专业发布总控</h2><p>聚合盲评接入、全片型评估、三角色签名、finalization candidate 与 durable release，为75个固定项目生成唯一最早NEXT。</p></div><nav><RouterLink to="/story/stage8-blind-review-intake">接入</RouterLink><RouterLink to="/story/stage8-blind-review-signature">签名</RouterLink><RouterLink to="/story/stage8-finalization-preflight">终局</RouterLink><RouterLink to="/story/stage8-durable-release-import">Release</RouterLink></nav></header>
    <div class="truth"><strong>Handoff ≠ External Completion ≠ Professional Pass</strong><span>只读汇总与内存交接；机器合同ready不能跳过真人证据、外部签名或独立release。</span></div>
    <p v-if="errorMessage" class="error">{{ errorMessage }}</p>
    <template v-if="report">
      <section class="summary"><article><span>固定项目</span><b>75</b></article><article><span>Intake Ready</span><b>{{ report.summary.blind_review_intake_ready_project_count }}</b></article><article><span>Evaluator Contract</span><b>{{ report.summary.evaluator_contract_ready_video_type_count }}/15</b></article><article><span>Signed Review</span><b>{{ report.summary.three_role_signature_ready_project_count }}</b></article><article><span>Candidate</span><b>{{ report.summary.finalization_candidate_ready_project_count }}</b></article><article><span>Release / Human / Pro</span><b class="zero">0 / 0 / 0</b></article></section>
      <section class="lanes"><article v-for="lane in report.lanes" :key="lane.lane_id"><header><span>{{ lane.label }}</span><b>{{ lane.current_count }}/{{ lane.target_count }}</b></header><div class="bar"><i :style="{width:`${lane.target_count?lane.current_count/lane.target_count*100:0}%`}"/></div><p>{{ lane.next_action }}</p><footer><small>{{ lane.blocker_count }} blockers · {{ lane.status }}</small><RouterLink :to="lane.route">打开</RouterLink></footer></article></section>
      <section class="main-grid">
        <article class="queue"><header><div><p class="eyebrow">UNIQUE EARLIEST NEXT</p><h3>{{ filteredProjects.length }} / 75 项外部动作</h3></div><div class="filters"><select v-model="videoTypeFilter"><option value="all">全部片型</option><option v-for="type in videoTypes" :key="type" :value="type">{{ type }}</option></select><select v-model="phaseFilter"><option value="all">全部阶段</option><option v-for="phase in phases" :key="phase" :value="phase">{{ phaseLabel(phase) }}</option></select></div></header><div class="task-list"><article v-for="project in filteredProjects" :key="project.benchmark_id"><div><span>{{ project.video_type }}</span><code>{{ project.benchmark_id }}</code></div><h4>{{ project.source_entry }}</h4><p>NEXT · {{ project.next_action.label }}</p><small>{{ phaseLabel(project.phase) }} · external input · 不计完成</small><RouterLink :to="project.next_action.route">前往门禁</RouterLink></article></div></article>
        <article class="handoff"><header><div><p class="eyebrow">MEMORY-ONLY HANDOFF</p><h3>75项目外部交接 JSON</h3></div><button @click="copyHandoff">{{ copyMessage || '复制 JSON' }}</button></header><textarea :value="handoffJson" aria-label="Stage 8 external handoff JSON" readonly/><div class="safety"><span>Persisted <b>否</b></span><span>Execution <b>否</b></span><span>Human pass <b>否</b></span><span>Release import <b>否</b></span><span>Professional <b>否</b></span><span>Source bindings <b>{{ report.source_bindings.length }}</b></span></div><details><summary>源报告 SHA-256</summary><p v-for="source in report.source_bindings" :key="source.path"><code>{{ source.path }}</code><small>{{ source.sha256 }}</small></p></details></article>
      </section>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import type { Stage8OperationsPhase,Stage8OperationsReport } from '@shared/types'
import { getStage8Operations } from '../api/stage8-blind-review'
const report=ref<Stage8OperationsReport|null>(null),errorMessage=ref(''),copyMessage=ref(''),videoTypeFilter=ref('all'),phaseFilter=ref('all')
const videoTypes=computed(()=>[...new Set(report.value?.projects.map(item=>item.video_type)??[])]),phases=computed(()=>[...new Set(report.value?.projects.map(item=>item.phase)??[])])
const filteredProjects=computed(()=>report.value?.projects.filter(item=>(videoTypeFilter.value==='all'||item.video_type===videoTypeFilter.value)&&(phaseFilter.value==='all'||item.phase===phaseFilter.value))??[])
const handoffJson=computed(()=>report.value?`${JSON.stringify(report.value.handoff_package,null,2)}\n`:'')
onMounted(async()=>{const response=await getStage8Operations();if(!response.ok||!response.data){errorMessage.value=response.error?.message??'Stage 8总控加载失败';return}report.value=response.data})
async function copyHandoff(){try{await navigator.clipboard.writeText(handoffJson.value);copyMessage.value='已复制'}catch{copyMessage.value='复制未授权'}window.setTimeout(()=>copyMessage.value='',1600)}
const phaseLabels:Record<Stage8OperationsPhase,string>={awaiting_blind_review_intake:'等待盲评接入',awaiting_external_review_bundle:'等待真人review bundle',awaiting_three_role_signatures:'等待三角色签名',awaiting_finalization_candidate:'等待finalization candidate',awaiting_durable_release_record:'等待durable release',awaiting_authorized_external_import:'等待授权外部导入'}
function phaseLabel(value:string){return phaseLabels[value as Stage8OperationsPhase]??value}
</script>

